    tensor conv305 = conv_2d(m["model.23.cv3.1.2"], act304, 1, 0);
    tensor rs306 = ggml_reshape_3d(m, ggml_cont(m, conv305), 1600, 80, 1);
    tensor dwconv307 = conv_2d_depthwise(m["model.23.cv3.2.0.0.conv"], act267, 1, 1);
    tensor act308 = ggml_silu_inplace(m, dwconv307);
    tensor conv309 = conv_2d(m["model.23.cv3.2.0.1.conv"], act308, 1, 0);
    tensor act310 = ggml_silu_inplace(m, conv309);
    tensor dwconv311 = conv_2d_depthwise(m["model.23.cv3.2.1.0.conv"], act310, 1, 1);
    tensor act312 = ggml_silu_inplace(m, dwconv311);
    tensor conv313 = conv_2d(m["model.23.cv3.2.1.1.conv"], act312, 1, 0);
    tensor act314 = ggml_silu_inplace(m, conv313);
    tensor conv315 = conv_2d(m["model.23.cv3.2.2"], act314, 1, 0);
    tensor rs316 = ggml_reshape_3d(m, ggml_cont(m, conv315), 400, 80, 1);
    tensor cat317 = ggml_concat(m, ggml_concat(m, rs296, rs306, 0), rs316, 0);
    tensor conv318 = conv_2d(m["model.23.one2one_cv2.0.0.conv"], act203, 1, 1);
    tensor act319 = ggml_silu_inplace(m, conv318);
    tensor conv320 = conv_2d(m["model.23.one2one_cv2.0.1.conv"], act319, 1, 1);
