    tensor rs335 = ggml_reshape_3d(m, ggml_cont(m, conv334), 400, 4, 1);
    tensor cat336 = ggml_concat(m, ggml_concat(m, rs323, rs329, 0), rs335, 0);
    tensor dwconv337 = conv_2d_depthwise(m["model.23.one2one_cv3.0.0.0.conv"], act203, 1, 1);
    tensor act338 = ggml_silu_inplace(m, dwconv337);
    tensor conv339 = conv_2d(m["model.23.one2one_cv3.0.0.1.conv"], act338, 1, 0);
    tensor act340 = ggml_silu_inplace(m, conv339);
    tensor dwconv341 = conv_2d_depthwise(m["model.23.one2one_cv3.0.1.0.conv"], act340, 1, 1);
    tensor act342 = ggml_silu_inplace(m, dwconv341);
    tensor conv343 = conv_2d(m["model.23.one2one_cv3.0.1.1.conv"], act342, 1, 0);
    tensor act344 = ggml_silu_inplace(m, conv343);
    tensor conv345 = conv_2d(m["model.23.one2one_cv3.0.2"], act344, 1, 0);
    tensor rs346 = ggml_reshape_3d(m, ggml_cont(m, conv345), 6400, 80, 1);
    tensor dwconv347 = conv_2d_depthwise(m["model.23.one2one_cv3.1.0.0.conv"], act230, 1, 1);
    tensor act348 = ggml_silu_inplace(m, dwconv347);
    tensor conv349 = conv_2d(m["model.23.one2one_cv3.1.0.1.conv"], act348, 1, 0);
    tensor act350 = ggml_silu_inplace(m, conv349);
    tensor dwconv351 = conv_2d_depthwise(m["model.23.one2one_cv3.1.1.0.conv"], act350, 1, 1);
    tensor act352 = ggml_silu_inplace(m, dwconv351);
    tensor conv353 = conv_2d(m["model.23.one2one_cv3.1.1.1.conv"], act352, 1, 0);
    tensor act354 = ggml_silu_inplace(m, conv353);
    tensor conv355 = conv_2d(m["model.23.one2one_cv3.1.2"], act354, 1, 0);
    tensor rs356 = ggml_reshape_3d(m, ggml_cont(m, conv355), 1600, 80, 1);
    tensor dwconv357 = conv_2d_depthwise(m["model.23.one2one_cv3.2.0.0.conv"], act267, 1, 1);
    tensor act358 = ggml_silu_inplace(m, dwconv357);
    tensor conv359 = conv_2d(m["model.23.one2one_cv3.2.0.1.conv"], act358, 1, 0);
    tensor act360 = ggml_silu_inplace(m, conv359);
    tensor dwconv361 = conv_2d_depthwise(m["model.23.one2one_cv3.2.1.0.conv"], act360, 1, 1);
    tensor act362 = ggml_silu_inplace(m, dwconv361);
    tensor conv363 = conv_2d(m["model.23.one2one_cv3.2.1.1.conv"], act362, 1, 0);
