    tensor cat367 = ggml_concat(m, ggml_concat(m, rs346, rs356, 0), rs366, 0);
    tensor ar370 = ggml_arange(m, 0.0f, 80.0f, 1.0f);
    tensor add371 = ggml_add(m, ar370, const5);
    tensor mg372 = ggml_repeat(m, add371, ggml_new_tensor_2d(m, GGML_TYPE_F32, 80, 80));
    tensor stk373 = ggml_concat(m, ggml_reshape_3d(m, mg372, 1, 80, 80), ggml_reshape_3d(m, mg372, 1, 80, 80), 0);
    tensor rs374 = ggml_reshape_2d(m, ggml_cont(m, stk373), 2, 6400);
    tensor full376 = ggml_fill(m, ggml_new_tensor_2d(m, GGML_TYPE_F32, 1, 6400), 8.0f);
