    tensor ar388 = ggml_arange(m, 0.0f, 20.0f, 1.0f);
    tensor add389 = ggml_add(m, ar388, const1);
    tensor mg390 = ggml_repeat(m, add389, ggml_new_tensor_2d(m, GGML_TYPE_F32, 20, 20));
    tensor stk391 = ggml_concat(m, ggml_reshape_3d(m, mg390, 1, 20, 20), ggml_reshape_3d(m, mg390, 1, 20, 20), 0);
    tensor rs392 = ggml_reshape_2d(m, ggml_cont(m, stk391), 2, 400);
    tensor full394 = ggml_fill(m, ggml_new_tensor_2d(m, GGML_TYPE_F32, 1, 400), 32.0f);
