    tensor add403 = ggml_add(m, uns399, sl401);
    tensor cat404 = ggml_concat(m, t402, add403, 1);
    tensor t405 = ggml_mul(m, cat404, t398);
    tensor t406 = ggml_sigmoid(m, ggml_concat(m, ggml_concat(m, rs346, rs356, 0), rs366, 0));
    tensor cat407 = ggml_concat(m, t405, t406, 1);

    tensor out_0 = compute_graph_output(m, contiguous_2d_to_cwhn(m, cat286), "out_0");
    tensor out_1 = compute_graph_output(m, contiguous_2d_to_cwhn(m, act203), "out_1");
